Chaos::FMassProperties ApplyMassPropertiesModifiers(const FBodyInstance* OwningBodyInstance, Chaos::FMassProperties MassProps, const FTransform& MassModifierTransform, const bool bInertaScaleIncludeMass)
{
	float OldMass = MassProps.Mass;
	float NewMass = 0.f;

	if (OwningBodyInstance->bOverrideMass == false)
	{
		// The mass was calculated assuming uniform density. RaiseMassToPower for values of less than 1.0
		// is used to correct this for objects where the density is higher closer to the surface.
		float RaiseMassToPower = 0.75f;
		if (UPhysicalMaterial* PhysMat = OwningBodyInstance->GetSimplePhysicalMaterial())
		{
			RaiseMassToPower = PhysMat->RaiseMassToPower;
		}

		float UsePow = FMath::Clamp<float>(RaiseMassToPower, UE_KINDA_SMALL_NUMBER, 1.f);
		NewMass = FMath::Pow(OldMass, UsePow);

		// Apply user-defined mass scaling.
		NewMass = FMath::Max(OwningBodyInstance->MassScale * NewMass, 0.001f);	//min weight of 1g
	}
	else
	{
		NewMass = FMath::Max(OwningBodyInstance->GetMassOverride(), 0.001f);	//min weight of 1g
	}

	float MassRatio = NewMass / OldMass;
	MassProps.Mass *= MassRatio;
	MassProps.InertiaTensor *= MassRatio;

		// TODO: For Transformed implicit, do not bake this in. Set Transform instead.
		Center = RelativeTM.TransformPosition(TaperedCapsuleElem->Center) * InScale3D;
		Axis = TaperedCapsuleElem->Rotation.RotateVector(Chaos::FVec3(0, 0, 1));
	}
	else
	{
		FKSphylElem* SphylElem = ShapeElem->GetShapeCheck<FKSphylElem>();

		const FReal InitialHeight = SphylElem->Radius * 2.0f + SphylElem->Length;
		Radius = FMath::Max(SphylElem->Radius * ScaleRadius, (FReal)0.1);
		HalfHeight = (SphylElem->Length * 0.5f + SphylElem->Radius) * ScaleLength;

		// TODO: For Transformed implicit, do not bake this in. Set Transform instead.
		Center = RelativeTM.TransformPosition(SphylElem->Center) * InScale3D;
		Axis = SphylElem->Rotation.RotateVector(Chaos::FVec3(0, 0, 1));
	}

	Radius = FMath::Min(Radius, HalfHeight);	//radius is capped by half length
	Radius = FMath::Max(Radius, (FReal)FCollisionShape::MinCapsuleRadius());
	FReal HalfLength = HalfHeight - Radius;
	HalfLength = FMath::Max((FReal)FCollisionShape::MinCapsuleAxisHalfHeight(), HalfLength);

	const FVec3 X1 = Center - HalfLength * Axis;
	const FVec3 X2 = Center + HalfLength * Axis;

	Chaos::FImplicitObjectPtr NewCapsule =  MakeImplicitObjectPtr<FCapsule>(X1, X2, Radius);
	NewGeometry.Emplace(MoveTemp(NewCapsule));

	bSuccess = true;

	break;
}
